24	    private static readonly ConnectorRef s_pim = ConnectorRef.Define("pim", Transport.File("./test/pim"));
25	    private static readonly ConnectorRef s_erp = ConnectorRef.Define("erp", Transport.File("./test/erp"));
26	
27	    private static SystemBuilder DeclareSystem()
28	    {
29	        var s = SystemBuilder.Create("product-distribution");
30	
31	        s.AddExtractor("pim-extractor")
32	            .From(s_pim)
33	            .Publishes(ProductFlow.Raw)
34	            .WithSchedule("*/5 * * * *");
35	
36	        s.AddTransactionalIntegration("pricing-service")
37	            .From(s_pim)
38	            .To(s_erp);
39	
40	        s.AddLoader("product-loader")
41	            .Subscribes(ProductFlow.Raw)
42	            .To(s_erp);
43	
44	        // An extractor whose source stays a private local component: no From edge.
45	        s.AddExtractor("price-extractor")
46	            .Publishes(PriceFlow.Raw);
47	
48	        // A loader whose destination stays a private local component: no To edge.
49	        s.AddLoader("price-loader")
50	            .Subscribes(PriceFlow.Raw);
