55	    [Fact]
56	    public void Build_WithSampleSystem_ShouldMaterializeFullTopology()
57	    {
58	        // Act
59	        var topology = DeclareSystem().Build();
60	
61	        // Assert: system + components
62	        Assert.Equal("product-distribution", topology.SystemName);
63	        Assert.Equal(["pim-extractor", "pricing-service", "product-loader", "price-extractor", "price-loader"],
64	            topology.Components.Select(w => w.Name));
65	
66	        var extractor = topology.Components[0];
67	        Assert.Equal(ConnectorDirection.In, Assert.Single(extractor.Connectors).Direction);
68	        Assert.Equal("default", Assert.Single(extractor.Publishes).Port);
69	        Assert.Equal("*/5 * * * *", extractor.Schedule);
70	
71	        var pricing = topology.Components[1];
