12	        s.AddExtractor("a").Publishes(TestTopics.Raw);
13	        s.AddLoader("d").Subscribes(TestTopics.Raw).To(TestConnectors.Erp);
14	        s.AddTransactionalIntegration("e").From(TestConnectors.Pim);
15	
16	        // Act
17	        var topology = s.Build();
18	
19	        // Assert
20	        Assert.Equal(["a", "d", "e"], topology.Components.Select(w => w.Name));
21	        Assert.Equal(
22	            [
23	                ComponentKind.Extractor,
24	                ComponentKind.Loader,
25	                ComponentKind.TransactionalIntegration,
26	            ],
27	            topology.Components.Select(w => w.Kind));
28	    }
