30	    [Fact]
31	    public void Subscribes_OnLoader_ShouldRecordSingleSubscription()
32	    {
33	        // Arrange
34	        var s = SystemBuilder.Create("test-system");
35	        s.AddLoader("loader").Subscribes(TestTopics.Raw).To(TestConnectors.Erp);
36	        s.AddExtractor("source").Publishes(TestTopics.Raw);
37	
38	        // Act
39	        var component = s.Build().Components[0];
40	
41	        // Assert
